package com.sphere.core.clhep.evaluator;

/**
 * Evaluator::setSystemOfUnits (Evaluator/src/setSystemOfUnits.cc): the SI units, their multiples and the
 * derived ones, in the base units given. Generated by gen_eval_units.py: CLHEP's statements, in their
 * order, the expressions unchanged.
 */
final class EvaluatorUnits {

    private EvaluatorUnits() {
    }

    static void set(Evaluator e, double meter, double kilogram, double second, double ampere, double kelvin,
                    double mole, double candela) {
        final double kilo_ = 1.e+03;
        final double mega_ = 1.e+06;
        final double giga_ = 1.e+09;
        final double tera_ = 1.e+12;
        final double peta_ = 1.e+15;
        final double deci_ = 1.e-01;
        final double centi_ = 1.e-02;
        final double milli_ = 1.e-03;
        final double micro_ = 1.e-06;
        final double nano_ = 1.e-09;
        final double pico_ = 1.e-12;
        final double m = meter;
        e.setVariable("meter", m);
        e.setVariable("metre", m);
        e.setVariable("m", m);
        final double kg = kilogram;
        e.setVariable("kilogram", kg);
        e.setVariable("kg", kg);
        final double s = second;
        e.setVariable("second", s);
        e.setVariable("s", s);
        final double A = ampere;
        e.setVariable("ampere", A);
        e.setVariable("amp", A);
        e.setVariable("A", A);
        final double K = kelvin;
        e.setVariable("kelvin", K);
        e.setVariable("K", K);
        final double mol = mole;
        e.setVariable("mole", mol);
        e.setVariable("mol", mol);
        final double cd = candela;
        e.setVariable("candela", cd);
        e.setVariable("cd", cd);
        final double rad = 1.;
        e.setVariable("radian", rad);
        e.setVariable("rad", rad);
        e.setVariable("milliradian", milli_ * rad);
        e.setVariable("mrad", milli_ * rad);
        final double pi = 3.14159265358979323846;
        final double deg = rad*pi/180.;
        e.setVariable("degree", deg);
        e.setVariable("deg", deg);
        final double sr = 1.;
        e.setVariable("steradian", sr);
        e.setVariable("sr", sr);
        final double Hz = 1./s;
        e.setVariable("hertz", Hz);
        e.setVariable("Hz", Hz);
        final double N = m * kg / (s*s);
        e.setVariable("newton", N);
        e.setVariable("N", N);
        final double Pa = N / (m*m);
        e.setVariable("pascal", Pa);
        e.setVariable("Pa", Pa);
        final double atm = 101325. * Pa;
        e.setVariable("atmosphere", atm);
        e.setVariable("atm", atm);
        final double bar = 100000*Pa;
        e.setVariable("bar", bar);
        final double J = N * m;
        e.setVariable("joule", J);
        e.setVariable("J", J);
        final double W = J / s;
        e.setVariable("watt", W);
        e.setVariable("W", W);
        final double C = A * s;
        e.setVariable("coulomb", C);
        e.setVariable("C", C);
        final double V = J / C;
        e.setVariable("volt", V);
        e.setVariable("V", V);
        final double ohm = V / A;
        e.setVariable("ohm", ohm);
        final double S = 1./ ohm;
        e.setVariable("siemens", S);
        e.setVariable("S", S);
        final double F = C / V;
        e.setVariable("farad", F);
        e.setVariable("F", F);
        final double T = V * s / (m*m);
        e.setVariable("tesla", T);
        e.setVariable("T", T);
        final double Gs = 1.e-4*T;
        e.setVariable("gauss", Gs);
        e.setVariable("Gs", Gs);
        final double Wb = V * s;
        e.setVariable("weber", Wb);
        e.setVariable("Wb", Wb);
        final double H = Wb / A;
        e.setVariable("henry", H);
        e.setVariable("H", H);
        final double lm = cd * sr;
        e.setVariable("lumen", lm);
        e.setVariable("lm", lm);
        final double lx = lm / (m*m);
        e.setVariable("lux", lx);
        e.setVariable("lx", lx);
        final double Bq = 1./s;
        e.setVariable("becquerel", Bq);
        e.setVariable("Bq", Bq);
        e.setVariable("kilobecquerel", kilo_ * Bq);
        e.setVariable("kBq", kilo_ * Bq);
        e.setVariable("megabecquerel", mega_ * Bq);
        e.setVariable("MBq", mega_ * Bq);
        e.setVariable("gigabecquerel", giga_ * Bq);
        e.setVariable("GBq", giga_ * Bq);
        e.setVariable("curie", 3.7e+10 * Bq);
        e.setVariable("Ci", 3.7e+10 * Bq);
        e.setVariable("millicurie", milli_ * 3.7e+10 * Bq);
        e.setVariable("mCi", milli_ * 3.7e+10 * Bq);
        e.setVariable("microcurie", micro_ * 3.7e+10 * Bq);
        e.setVariable("uCi", micro_ * 3.7e+10 * Bq);
        final double Gy = J / kg;
        e.setVariable("gray", Gy);
        e.setVariable("Gy", Gy);
        e.setVariable("kilogray", kilo_ * Gy);
        e.setVariable("milligray", milli_ * Gy);
        e.setVariable("microgray", micro_ * Gy);
        final double Sv = J / kg;
        e.setVariable("sievert", Sv);
        e.setVariable("Sv", Sv);
        final double mm = milli_ * m;
        e.setVariable("millimeter", mm);
        e.setVariable("mm", mm);
        final double cm = centi_ * m;
        e.setVariable("centimeter", cm);
        e.setVariable("cm", cm);
        e.setVariable("decimeter", deci_ * m);
        final double km = kilo_ * m;
        e.setVariable("kilometer", km);
        e.setVariable("km", km);
        e.setVariable("micrometer", micro_ * m);
        e.setVariable("micron", micro_ * m);
        e.setVariable("um", micro_ * m);
        e.setVariable("nanometer", nano_ * m);
        e.setVariable("nm", nano_ * m);
        final double parsec = 3.0856775807e+16 * m;
        e.setVariable("parsec", parsec);
        e.setVariable("pc", parsec);
        e.setVariable("angstrom", 1.e-10 * m);
        e.setVariable("fermi", 1.e-15 * m);
        e.setVariable("m2", m*m);
        e.setVariable("mm2", mm*mm);
        e.setVariable("cm2", cm*cm);
        e.setVariable("km2", km*km);
        final double barn = 1.e-28 * m*m;
        e.setVariable("barn", barn);
        e.setVariable("millibarn", milli_ * barn);
        e.setVariable("mbarn", milli_ * barn);
        e.setVariable("microbarn", micro_ * barn);
        e.setVariable("nanobarn", nano_ * barn);
        e.setVariable("picobarn", pico_ * barn);
        e.setVariable("m3", m*m*m);
        e.setVariable("mm3", mm*mm*mm);
        e.setVariable("cm3", cm*cm*cm);
        e.setVariable("cc", cm*cm*cm);
        e.setVariable("km3", km*km*km);
        final double L = 1.e-3*m*m*m;
        e.setVariable("liter", L);
        e.setVariable("litre", L);
        e.setVariable("L", L);
        e.setVariable("centiliter", centi_ * L);
        e.setVariable("cL", centi_ * L);
        e.setVariable("milliliter", milli_ * L);
        e.setVariable("mL", milli_ * L);
        final double dpt = 1./m;
        e.setVariable("diopter", dpt);
        e.setVariable("dioptre", dpt);
        e.setVariable("dpt", dpt);
        final double g = 0.001*kg;
        e.setVariable("gram", g);
        e.setVariable("g", g);
        e.setVariable("milligram", milli_ * g);
        e.setVariable("mg", milli_ * g);
        e.setVariable("millisecond", milli_ * s);
        e.setVariable("ms", milli_ * s);
        e.setVariable("microsecond", micro_ * s);
        e.setVariable("us", micro_ * s);
        e.setVariable("nanosecond", nano_ * s);
        e.setVariable("ns", nano_ * s);
        e.setVariable("picosecond", pico_ * s);
        e.setVariable("ps", pico_ * s);
        final double minute = 60*s;
        e.setVariable("minute", minute);
        final double hour = 60*minute;
        e.setVariable("hour", hour);
        final double day = 24*hour;
        e.setVariable("day", day);
        final double year = 365*day;
        e.setVariable("year", year);
        e.setVariable("milliampere", milli_ * A);
        e.setVariable("mA", milli_ * A);
        e.setVariable("microampere", micro_ * A);
        e.setVariable("nanoampere", nano_ * A);
        e.setVariable("kilohertz", kilo_ * Hz);
        e.setVariable("kHz", kilo_ * Hz);
        e.setVariable("megahertz", mega_ * Hz);
        e.setVariable("MHz", mega_ * Hz);
        e.setVariable("kilonewton", kilo_ * N);
        e.setVariable("kN", kilo_ * N);
        e.setVariable("kilobar", kilo_ * bar);
        e.setVariable("kbar", kilo_ * bar);
        e.setVariable("millibar", milli_ * bar);
        e.setVariable("mbar", milli_ * bar);
        e.setVariable("kilojoule", kilo_ * J);
        e.setVariable("kJ", kilo_ * J);
        e.setVariable("megajoule", mega_ * J);
        e.setVariable("MJ", mega_ * J);
        e.setVariable("gigajoule", giga_ * J);
        e.setVariable("GJ", giga_ * J);
        final double e_SI = 1.602176634e-19;
        final double ePlus = e_SI * C;
        final double eV = ePlus * V;
        e.setVariable("electronvolt", eV);
        e.setVariable("eV", eV);
        e.setVariable("millielectronvolt", milli_ * eV);
        e.setVariable("kiloelectronvolt", kilo_ * eV);
        e.setVariable("keV", kilo_ * eV);
        e.setVariable("megaelectronvolt", mega_ * eV);
        e.setVariable("MeV", mega_ * eV);
        e.setVariable("gigaelectronvolt", giga_ * eV);
        e.setVariable("GeV", giga_ * eV);
        e.setVariable("teraelectronvolt", tera_ * eV);
        e.setVariable("TeV", tera_ * eV);
        e.setVariable("petaelectronvolt", peta_ * eV);
        e.setVariable("PeV", peta_ * eV);
        e.setVariable("kilowatt", kilo_ * W);
        e.setVariable("kW", kilo_ * W);
        e.setVariable("megawatt", mega_ * W);
        e.setVariable("MW", mega_ * W);
        e.setVariable("gigawatt", giga_ * W);
        e.setVariable("GW", giga_ * W);
        e.setVariable("kilovolt", kilo_ * V);
        e.setVariable("kV", kilo_ * V);
        e.setVariable("megavolt", mega_ * V);
        e.setVariable("MV", mega_ * V);
        e.setVariable("millifarad", milli_ * F);
        e.setVariable("mF", milli_ * F);
        e.setVariable("microfarad", micro_ * F);
        e.setVariable("uF", micro_ * F);
        e.setVariable("nanofarad", nano_ * F);
        e.setVariable("nF", nano_ * F);
        e.setVariable("picofarad", pico_ * F);
        e.setVariable("pF", pico_ * F);
        e.setVariable("kilogauss", kilo_ * Gs);
        e.setVariable("kGs", kilo_ * Gs);
    }
}
